74	export class PageTheatreBinder {
75	  private _pageId: string | null;
76	  private _sceneRequestId = 0;
77	  private _adapterPromise: Promise<PageTheatreAdapter | null> | null = null;
78	  private _sceneSyncPortPromise: Promise<PageSceneSyncPort<string, string> | null> | null =
79	    null;
80	
81	  constructor(pageId?: string | null) {
82	    this._pageId = pageId ?? null;
83	  }
84	
85	  setPageId(pageId: string): void {
86	    if (this._pageId === pageId) return;
87	    this._pageId = pageId;
88	    this._adapterPromise = null;
89	    this._sceneSyncPortPromise = null;
90	    this._sceneRequestId = 0;
91	  }
92	
93	  async applyBootStateIfNeeded(engine: Engine): Promise<void> {
94	    const adapter = await this._getAdapter();
95	    await adapter?.applyBootStateIfNeeded?.(engine);
96	  }
97	
98	  async startPreviewIfNeeded(engine: Engine): Promise<void> {
99	    const adapter = await this._getAdapter();
100	    await adapter?.startPreviewIfNeeded?.(engine);
101	  }
102	
103	  async startAfterIntroIfNeeded(engine: Engine): Promise<void> {
104	    const adapter = await this._getAdapter();
105	    await adapter?.startAfterIntroIfNeeded?.(engine);
106	  }
107	
108	  async startIntroIfNeeded(engine: Engine): Promise<void> {
109	    const adapter = await this._getAdapter();
110	    await adapter?.startIntroIfNeeded?.(engine);
111	  }
112	
113	  async startIntroActionPhaseOneIfNeeded(engine: Engine): Promise<void> {
114	    const adapter = await this._getAdapter();
115	    await adapter?.startIntroActionPhaseOneIfNeeded?.(engine);
116	  }
117	
118	  async startIntroActionPhaseTwoIfNeeded(engine: Engine): Promise<void> {
119	    const adapter = await this._getAdapter();
120	    await adapter?.startIntroActionPhaseTwoIfNeeded?.(engine);
121	  }
122	
123	  dispose(): void {
124	    void this._disposeAsync();
125	  }
126	
127	  syncScene<TSceneKey extends string, TSheetId extends string>(
128	    engine: Engine,
129	    sceneKey: TSceneKey,
130	    progress: number,
131	    onSheetChange: (sheetId: TSheetId | null) => void,
132	  ): void {
133	    const requestId = ++this._sceneRequestId;
134	    void this._syncScene(engine, sceneKey, progress, requestId, onSheetChange);
135	  }
136	
137	  private _getAdapter(): Promise<PageTheatreAdapter | null> {
138	    if (this._adapterPromise) return this._adapterPromise;
139	    this._adapterPromise = this._createAdapter();
140	    return this._adapterPromise;
141	  }
142	
143	  private async _createAdapter(): Promise<PageTheatreAdapter | null> {
144	    const pageType = this._pageId;
145	    if (!pageType) return null;
146	    const factory = PAGE_THEATRE_ADAPTER_FACTORIES[pageType];
147	    if (!factory) return null;
148	    return factory();
149	  }
150	
151	  private async _getSceneSyncPort(): Promise<PageSceneSyncPort<string, string> | null> {
152	    if (this._sceneSyncPortPromise) return this._sceneSyncPortPromise;
153	    this._sceneSyncPortPromise = this._createSceneSyncPort();
154	    return this._sceneSyncPortPromise;
155	  }
156	
157	  private async _createSceneSyncPort(): Promise<PageSceneSyncPort<string, string> | null> {
158	    const adapter = await this._getAdapter();
159	    return (await adapter?.getSceneSyncPort?.()) ?? null;
160	  }
161	
162	  private async _syncScene<TSceneKey extends string, TSheetId extends string>(
163	    engine: Engine,
164	    sceneKey: TSceneKey,
165	    progress: number,
166	    requestId: number,
167	    onSheetChange: (sheetId: TSheetId | null) => void,
168	  ): Promise<void> {
169	    const port = await this._getSceneSyncPort();
170	    if (!port || requestId !== this._sceneRequestId) return;
171	    onSheetChange(port.apply(engine, sceneKey, progress) as TSheetId | null);
172	  }
173	
174	  private async _disposeAsync(): Promise<void> {
175	    const adapter = await this._getAdapter();
176	    await adapter?.stopPreview?.();
177	  }
178	}
