150	class FeatureCardCanvasRuntime {
151	  private _instances: FeatureCardCanvasInstance[] = [];
152	  private _rafId: number | null = null;
153	  private _resizeListener: (() => void) | null = null;
154	
155	  init(root?: ParentNode | null): void {
156	    this.dispose();
157	    const scope = root ?? document;
158	    const cardList = scope.querySelector<HTMLElement>(
159	      FEATURE_CARD_CANVAS.listSelector,
160	    );
161	    if (!cardList) return;
162	    const canvasElements = Array.from(
163	      cardList.querySelectorAll<HTMLCanvasElement>(
164	        FEATURE_CARD_CANVAS.canvasSelector,
165	      ),
166	    );
167	    if (canvasElements.length === 0) return;
168	
169	    this._instances = canvasElements.flatMap((canvas, index) => {
170	      const context = canvas.getContext("2d");
171	      if (!context) return [];
172	      return [
173	        {
174	          canvas,
175	          context,
176	          size: { width: 0, height: 0, dpr: 1 },
177	          rotation: index * 0.45,
178	          tilt: 0.6 + index * 0.18,
179	          speed:
180	            FEATURE_CARD_CANVAS.rotationSpeedBase +
181	            index * FEATURE_CARD_CANVAS.rotationSpeedStep,
182	          particles: this._createParticles(index),
183	        },
184	      ];
185	    });
186	
187	    if (this._instances.length === 0) return;
188	
189	    this._resizeListener = () => this._resize();
190	    window.addEventListener("resize", this._resizeListener);
191	    this._resize();
192	    this._startLoop();
193	  }
194	
195	  dispose(): void {
196	    if (this._rafId !== null) {
197	      FrameScheduler.cancel(this._rafId);
198	      this._rafId = null;
199	    }
200	    if (this._resizeListener) {
201	      window.removeEventListener("resize", this._resizeListener);
202	      this._resizeListener = null;
203	    }
204	    this._instances = [];
205	  }
206	
207	  private _startLoop(): void {
208	    const render = (): void => {
209	      this._render();
210	      this._rafId = FrameScheduler.request(render);
211	    };
212	    render();
213	  }
214	
215	  private _resize(): void {
216	    const dpr = Math.min(
217	      ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
218	      FEATURE_CARD_CANVAS.pixelRatioMax,
219	    );
220	    this._instances.forEach((instance) => {
221	      const bounds = instance.canvas.getBoundingClientRect();
222	      const width = Math.max(1, Math.round(bounds.width));
223	      const height = Math.max(1, Math.round(bounds.height));
224	      instance.size = { width, height, dpr };
225	      instance.canvas.width = Math.round(width * dpr);
226	      instance.canvas.height = Math.round(height * dpr);
227	      instance.context.setTransform(dpr, 0, 0, dpr, 0, 0);
228	    });
229	  }
230	
231	  private _render(): void {
232	    this._instances.forEach((instance) => {
233	      const { context, size } = instance;
234	      if (size.width <= 0 || size.height <= 0) return;
235	
236	      instance.rotation += instance.speed;
237	      context.clearRect(0, 0, size.width, size.height);
238	      context.fillStyle = FEATURE_CARD_CANVAS.clearColor;
239	      context.fillRect(0, 0, size.width, size.height);
240	
241	      this._drawParticles(instance);
242	      this._drawCube(instance);
243	    });
244	  }
245	
246	  private _drawParticles(instance: FeatureCardCanvasInstance): void {
247	    const { context, size, rotation, particles } = instance;
248	    const halfWidth = size.width * 0.5;
249	    const halfHeight = size.height * 0.5;
250	    const scale =
251	      Math.min(size.width, size.height) * FEATURE_CARD_CANVAS.cubeScale;
252	
253	    context.fillStyle = FEATURE_CARD_CANVAS.particleColor;
254	    particles.forEach((particle) => {
255	      const spin = rotation * (0.6 + particle.drift * 0.4);
256	      const cos = Math.cos(spin);
257	      const sin = Math.sin(spin);
258	      const rotatedX = particle.x * cos - particle.z * sin;
259	      const rotatedZ = particle.x * sin + particle.z * cos;
260	      const depth = rotatedZ + 3.6;
261	      const perspective = 1 / depth;
262	      const drawX = halfWidth + rotatedX * scale * perspective;
263	      const drawY =
264	        halfHeight +
265	        (particle.y + Math.sin(rotation + particle.drift) * 0.14) *
266	          scale *
267	          perspective;
268	      const drawSize = particle.size * perspective * 4.5;
269	      context.fillRect(drawX, drawY, drawSize, drawSize);
270	    });
271	  }
272	
273	  private _drawCube(instance: FeatureCardCanvasInstance): void {
274	    const { context, size, rotation, tilt } = instance;
275	    const halfWidth = size.width * 0.5;
276	    const halfHeight = size.height * 0.5;
277	    const scale =
278	      Math.min(size.width, size.height) * FEATURE_CARD_CANVAS.cubeScale;
279	    const projected = FEATURE_CARD_CUBE_VERTICES.map(([x, y, z]) => {
280	      const rotatedY = this._rotateY(x, z, rotation);
281	      const rotatedX = this._rotateX(y, rotatedY.z, tilt);
282	      const depth = rotatedX.z + 4.2;
283	      const perspective = 1 / depth;
284	      return {
285	        x: halfWidth + rotatedY.x * scale * perspective,
286	        y: halfHeight + rotatedX.y * scale * perspective,
287	      };
288	    });
289	
290	    context.fillStyle = FEATURE_CARD_CANVAS.fillStyle;
291	    context.beginPath();
292	    context.moveTo(projected[4].x, projected[4].y);
293	    context.lineTo(projected[5].x, projected[5].y);
294	    context.lineTo(projected[6].x, projected[6].y);
295	    context.lineTo(projected[7].x, projected[7].y);
296	    context.closePath();
297	    context.fill();
298	
299	    context.strokeStyle = FEATURE_CARD_CANVAS.strokeStyle;
300	    context.lineWidth = 1.2;
301	    FEATURE_CARD_CUBE_EDGES.forEach(([startIndex, endIndex]) => {
302	      const start = projected[startIndex];
303	      const end = projected[endIndex];
304	      context.beginPath();
305	      context.moveTo(start.x, start.y);
306	      context.lineTo(end.x, end.y);
307	      context.stroke();
308	    });
309	  }
310	
311	  private _createParticles(index: number): FeatureCardCanvasParticle[] {
312	    return Array.from(
313	      { length: FEATURE_CARD_CANVAS.particleCount },
314	      (_, particleIndex) => {
315	        const seed = (index + 1) * (particleIndex + 3);
316	        const angle = seed * 0.73;
317	        const radius = 1.2 + (particleIndex % 5) * 0.18;
318	        return {
319	          x: Math.cos(angle) * radius,
320	          y: (((particleIndex % 7) - 3) / 3) * 1.35,
321	          z: Math.sin(angle) * radius,
322	          size:
323	            FEATURE_CARD_CANVAS.particleSizeMin +
324	            (particleIndex % 4) *
325	              ((FEATURE_CARD_CANVAS.particleSizeMax -
326	                FEATURE_CARD_CANVAS.particleSizeMin) /
327	                3),
328	          drift: 0.8 + (particleIndex % 6) * 0.12,
329	        };
330	      },
331	    );
332	  }
333	
334	  private _rotateY(
335	    x: number,
336	    z: number,
337	    angle: number,
338	  ): { x: number; z: number } {
339	    const cos = Math.cos(angle);
340	    const sin = Math.sin(angle);
341	    return {
342	      x: x * cos - z * sin,
343	      z: x * sin + z * cos,
344	    };
345	  }
346	
347	  private _rotateX(
348	    y: number,
349	    z: number,
350	    angle: number,
351	  ): { y: number; z: number } {
352	    const cos = Math.cos(angle);
353	    const sin = Math.sin(angle);
354	    return {
355	      y: y * cos - z * sin,
356	      z: y * sin + z * cos,
357	    };
358	  }
359	}
