361	export class PageRuntime {
362	  private controller: PageController | null = null;
363	  private bootTask: Promise<void> | null = null;
364	  private readonly _globalUiRuntime = new PageGlobalUiRuntime();
365	  private readonly _featureCardCanvasRuntime = new FeatureCardCanvasRuntime();
366	  private readonly _subpageStarfieldRuntime = new SubpageStarfieldRuntime();
367	
368	  async runPage(root?: HTMLElement): Promise<void> {
369	    if (this.bootTask) return this.bootTask;
370	
371	    this.bootTask = (async () => {
372	      this._disposePageRuntime();
373	      this.disposeController();
374	
375	      if ("scrollRestoration" in history) {
376	        history.scrollRestoration = "manual";
377	      }
378	      window.scrollTo({ top: 0, behavior: "auto" });
379	
380	      this._globalUiRuntime.init(root);
381	      this._featureCardCanvasRuntime.init(root);
382	      this._subpageStarfieldRuntime.init(root);
383	
384	      this.controller = new PageController();
385	      await this.controller.init(root);
386	    })().finally(() => {
387	      this.bootTask = null;
388	    });
389	
390	    return this.bootTask;
391	  }
392	
393	  syncAfterContainerChange(): void {
394	    this._globalUiRuntime.syncAfterContainerChange();
395	  }
396	
397	  disposeController(): void {
398	    this.controller?.dispose();
399	    this.controller = null;
400	    this.bootTask = null;
401	    TimelineRuntime.clear();
402	  }
403	
404	  dispose(): void {
405	    this.disposeController();
406	    this._disposePageRuntime();
407	    TimelineRuntime.clear();
408	  }
409	
410	  private _disposePageRuntime(): void {
411	    try {
412	      this._globalUiRuntime.dispose();
413	    } catch (error) {
414	      console.warn(
415	        "[PageRuntime._disposePageRuntime] Global UI cleanup failed.",
416	        error,
417	      );
418	    }
419	    try {
420	      this._featureCardCanvasRuntime.dispose();
421	    } catch (error) {
422	      console.warn(
423	        "[PageRuntime._disposePageRuntime] Feature card canvas cleanup failed.",
424	        error,
425	      );
426	    }
427	    try {
428	      this._subpageStarfieldRuntime.dispose();
429	    } catch (error) {
430	      console.warn(
431	        "[PageRuntime._disposePageRuntime] Subpage starfield cleanup failed.",
432	        error,
433	      );
434	    }
435	  }
436	}
